cd /workspace; python3 -I - <<'EOF'
import json, ast, collections, warnings
warnings.filterwarnings("ignore")
p="data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl"
rows=[json.loads(l) for l in open(p) if l.strip()]
# positions of duplicate keys
pos=collections.defaultdict(list)
for i,r in enumerate(rows): pos[(r["scenario"],r["task_idx"])].append(i)
print("duplicate positions:")
for k,v in pos.items():
    if len(v)>1: print(k,v, [len(rows[i]["verification"]["code"]) for i in v])
# unusual defs
for i,r in enumerate(rows):
    c=r["verification"]["code"]
    defs=[l.strip() for l in c.split("\n") if l.strip().startswith("def ")]
    if not any(d.startswith("def verify_task_completion(") for d in defs):
        print("ODD DEF",i,r["scenario"],r["task_idx"],defs[:6])
# syntax errors and where
for i,r in enumerate(rows):
    try: ast.parse(r["verification"]["code"])
    except SyntaxError as e: print("SYNTAX ERR at idx",i,r["scenario"],r["task_idx"],e)
EOF

