import json,re,collections
def norm(s):
    s=s.lower(); s=re.sub(r'[^a-z0-9_]','_',s); s=re.sub(r'_+','_',s).strip('_').strip(); return s
T=[json.loads(l) for l in open("data/AgentWorldModel-1K/gen_tasks.jsonl")]
scens=[t["scenario"] for t in T]
print("n",len(scens),"unique raw",len(set(scens)),"unique norm",len(set(map(norm,scens))))
c=collections.defaultdict(list)
for s in scens: c[norm(s)].append(s)
coll={k:v for k,v in c.items() if len(v)>1}
print("collisions",len(coll))
for k,v in list(coll.items())[:20]: print(k,v)
print("non-ascii or weird", [s for s in scens if norm(s)!=s][:10])
# test keys anomalies
import pyarrow.parquet as pq
te=pq.read_table("data/AgentWorldModel-1K/verl/test.parquet").to_pylist()
V=[json.loads(l) for l in open("data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl")]
first={}
for i,v in enumerate(V):
    k=(norm(v["scenario"]), v["task_idx"])
    first.setdefault(k,[]).append(i)
print("test entries:")
for r in te:
    ek=r["env_kwargs"]; k=(norm(ek["scenario"]),ek["task_idx"])
    ids=first.get(k,[])
    print(ek["scenario"],ek["task_idx"],"idx",ids,"first_valid?",end=" ")
    if ids:
        import ast
        try: ast.parse(V[ids[0]]["verification"]["code"]); print("ok", "nmatches",len(ids))
        except Exception as e: print("BAD",e)
    else: print("MISSING")
EOF

