arguments.command:
python3 -I - <<'PY'
import json,ast,collections
rows=[json.loads(l) for l in open('/workspace/data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl') if l.strip()]
sigc=collections.Counter(); retc=collections.Counter(); weird=[]
for i,r in enumerate(rows):
    code=r.get('verification',{}).get('code','')
    try: tree=ast.parse(code)
    except SyntaxError: continue
    fns=[n for n in tree.body if isinstance(n,ast.FunctionDef)]
    if not fns: weird.append((i,r['scenario'],r['task_idx'],'no top fn')); continue
    # find first verify_ fn
    fn=None
    for f in fns:
        if f.name.startswith('verify_'): fn=f; break
    if fn is None: fn=fns[0]
    args=[a.arg for a in fn.args.args]
    sigc[tuple(args)]+=1
    rets=[]
    for n in ast.walk(fn):
        if isinstance(n,ast.Return):
            v=n.value
            if isinstance(v,ast.Dict):
                keys=[k.value for k in v.keys if isinstance(k,ast.Constant)]
                rets.append('dict:'+','.join(map(str,keys)))
            elif isinstance(v,ast.Constant):
                rets.append('const:'+repr(v.value)[:20])
            elif isinstance(v,ast.Call):
                rets.append('call:'+getattr(v.func,'id',getattr(v.func,'attr','?')))
            else:
                rets.append(type(v).__name__)
    retc[tuple(sorted(set(rets)))]+=1
print('signatures:')
for k,v in sigc.most_common(20): print(v,k)
print('\nreturn patterns:')
for k,v in retc.most_common(30): print(v,k)
print('\nweird',len(weird))
for w in weird[:20]: print(w)
PY

