def getcode(e):
    v = e.get("verification") or {}
    for k in ("code","pure_code","verifier_code","source_code"):
        if isinstance(v.get(k), str) and v.get(k).strip():
            return v[k], k
    # search any str containing def verify
    for k,val in v.items():
        if isinstance(val,str) and "def verify" in val:
            return val, k
    for k,val in e.items():
        if isinstance(val,str) and "def verify" in val:
            return val, k
    return "", None
