    name = e.get("scenario"); ti = e.get("task_idx")
    keys[(name,ti)].append(ln)
    defs = re.findall(r"def\s+(verify_[A-Za-z0-9_]*)\s*\(", code)
    if not defs: nodef.append((ln,name,ti,field))
    if len(defs)>1: multi.append((ln,name,ti,defs))
