def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from datetime import datetime
    from dateutil.relativedelta import relativedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    if not final_answer or len(final_answer.strip()) < 20:
        return {"result": "others"}

    # Calculate cutoff date: 5 years before 2025-12-31 is 2020-12-31
    reference_date = datetime(2025, 12, 31)
    cutoff_date = datetime(2020, 12, 31)

    # Query assets older than 5 years as of 2025-12-31
    query_assets = """
        SELECT a.id, a.asset_tag, a.purchase_date, a.asset_type_id, at.name
        FROM assets a
        JOIN asset_types at ON a.asset_type_id = at.id
        WHERE DATE(a.purchase_date) <= '2020-12-31'
    """
    old_assets = safe_query(final_db_path, query_assets)

    if not old_assets:
        return {"result": "others"}

    # Calculate age in months and build expected data
    asset_info = {}
    asset_type_ages = {}

    for asset_id, asset_tag, purchase_date_str, asset_type_id, asset_type_name in old_assets:
        try:
            purchase_date = datetime.strptime(purchase_date_str, '%Y-%m-%d')
            age_months = (reference_date.year - purchase_date.year) * 12 + (reference_date.month - purchase_date.month)

            asset_info[asset_id] = {
                'tag': asset_tag,
                'age_months': age_months,
                'type_id': asset_type_id,
                'type_name': asset_type_name
            }

            if asset_type_name not in asset_type_ages:
                asset_type_ages[asset_type_name] = []
            asset_type_ages[asset_type_name].append(age_months)
        except:
            continue

    # Query revenue by asset for qualifying assets
    asset_ids_str = ','.join(str(aid) for aid in asset_info.keys())
    if not asset_ids_str:
        return {"result": "others"}

    query_revenue = f"""
        SELECT r.asset_id, SUM(r.revenue_amount) as total_revenue
        FROM revenue_by_asset r
        WHERE r.asset_id IN ({asset_ids_str})
        GROUP BY r.asset_id
    """
    revenue_data = safe_query(final_db_path, query_revenue)

    # Aggregate revenue by asset type
    revenue_by_type = {}
    for asset_id, total_revenue in revenue_data:
        if asset_id in asset_info:
            type_name = asset_info[asset_id]['type_name']
            if type_name not in revenue_by_type:
                revenue_by_type[type_name] = 0.0
            revenue_by_type[type_name] += float(total_revenue)

    # Calculate average age per asset type
    avg_age_by_type = {}
    for type_name, ages in asset_type_ages.items():
        if ages:
            avg_age_by_type[type_name] = sum(ages) / len(ages)

    # Get top 5 asset types by revenue
    sorted_types = sorted(revenue_by_type.items(), key=lambda x: x[1], reverse=True)[:5]

    if len(sorted_types) < 5:
        return {"result": "others"}

    # Verification checks
    final_lower = final_answer.lower()

    # Check 1: At least some old asset identifiers should be mentioned
    asset_mention_count = 0
    for asset_id, info in asset_info.items():
        if info['tag'].lower() in final_lower or str(asset_id) in final_answer:
            asset_mention_count += 1

    if asset_mention_count < 3:
        return {"result": "others"}

    # Check 2: Top 5 asset type names should be mentioned
    top_5_type_names = [name for name, _ in sorted_types]
    type_mention_count = 0
    for type_name in top_5_type_names:
        if type_name.lower() in final_lower:
            type_mention_count += 1

    if type_mention_count < 4:
        return {"result": "others"}

    # Check 3: Revenue values should be present and roughly match
    revenue_match_count = 0
    for type_name, expected_revenue in sorted_types:
        # Look for revenue values near the expected amount
        revenue_int = int(expected_revenue)
        # Check for exact match or within 10% tolerance
        patterns = [
            rf'{revenue_int}',
            rf'{expected_revenue:.2f}',
            rf'{expected_revenue:.0f}'
        ]
        for pattern in patterns:
            if pattern in final_answer:
                revenue_match_count += 1
                break

    if revenue_match_count < 3:
        return {"result": "others"}

    # Check 4: Average age values should be mentioned
    age_mention_count = 0
    for type_name in top_5_type_names:
        if type_name in avg_age_by_type:
            avg_age = avg_age_by_type[type_name]
