from pathlib import Path

data=Path('/workspace/data/AgentWorldModel-1K')
# load data
def load(name):
    return [json.loads(l) for l in open(data/f'{name}.jsonl') if l.strip()]
tasks=load('gen_tasks'); dbs=load('gen_db'); samples=load('gen_sample'); vers=load('gen_verifier.pure_code')
dbmap={r['scenario']:r for r in dbs}; smap={r['scenario']:r for r in samples}
kmap={(r['scenario'],r['task_idx']):i for i,r in enumerate(vers)}
