    from awm.core.verify import execute_code_verifier
    print('imported awm verify OK')
except Exception as e:
    print('import failed',e); execute_code_verifier=None

def make_db(scenario, outdir):
    schema=dbmap[scenario]['db_schema']; sample=smap[scenario]['sample_data']
    path=os.path.join(outdir, scenario+'.db')
    if os.path.exists(path): os.remove(path)
    conn=sqlite3.connect(path); cur=conn.cursor()
    for t in schema.get('tables',[]):
        try:
            cur.execute(t['ddl'])
            for s in t.get('indexes',[]): cur.execute(s)
            for s in t.get('examples',[]): cur.execute(s)
        except Exception as e:
            print('schema err',scenario,t.get('name'),e)
    conn.commit(); conn.close()
    conn=sqlite3.connect(path); cur=conn.cursor(); cur.execute('PRAGMA foreign_keys = ON;')
    ok=fail=0
    for t in sample.get('tables',[]):
        for s in t.get('insert_statements',[]):
            try: cur.execute(s); ok+=1
            except Exception as e: fail+=1
    conn.commit(); conn.close()
    return path,ok,fail

def call(code, init, final, answer):
    # mimic execute_code_verifier but with our own namespace
    ns={'sqlite3':sqlite3,'json':json,'os':os,'re':__import__('re'),'__builtins__':__builtins__}
    try:
        exec(code, ns)
    except Exception as e:
        return {'exec':'error','err':f'compile/exec: {e}'}
    f=None
    for line in code.split('\n'):
        s=line.strip()
        if s.startswith('def verify_') and '(' in s:
            name=s.split('(')[0].replace('def ','').strip(); f=ns.get(name); break
    if f is None: return {'exec':'error','err':'no func'}
    try:
        import inspect
        sig=inspect.signature(f); params=sig.parameters
        kw={}
        if 'initial_db_path' in params: kw['initial_db_path']=init
        if 'final_db_path' in params: kw['final_db_path']=final
        if 'final_answer' in params: kw['final_answer']=answer or ''
        if not kw and len(params)>=2:
            args=[init,final]; 
            if len(params)>=3: args.append(answer or '')
            r=f(*args)
        else:
            r=f(**kw)
        return {'exec':'ok','ret':r if isinstance(r,(dict,str,bool,type(None))) else str(r)[:100]}
    except Exception as e:
        return {'exec':'error','err':f'{type(e).__name__}: {e}'}

dups={}
for i,r in enumerate(vers):
    k=(r['scenario'],r['task_idx'])
    if k in dups: dups[k].append(i)
    else: dups[k]=[i]
dups={k:v for k,v in dups.items() if len(v)>1}
outdir=tempfile.mkdtemp(prefix='awm_dbs_',dir='/tmp/awk')
print('dbdir',outdir)
for (scenario,ti),idxs in sorted(dups.items()):
    path,ok,fail=make_db(scenario,outdir)
    print('\n===',scenario,ti,'inserts',ok,fail,'idx',idxs)
    for i in idxs:
        code=vers[i]['verification']['code']
        r=call(code,path,path,'')
        print(' idx',i,r)
    # also plausible canned answers for read-only tasks

